def find_man_holding_phone(image):
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    phone_patches = image_patch.find("phone")

    man_holding_phone = []
    for man in man_patches:
        for phone in phone_patches:
            if man.overlaps_with(phone.left, phone.lower, phone.right, phone.upper):
                man_holding_phone.append(man)

    if not man_holding_phone:
        return "No man holding a phone found in the image."

    # If multiple men are holding the phone, return the one with the largest overlap
    man_holding_phone.sort(key=lambda man: (man.right - man.left) * (man.upper - man.lower), reverse=True)

    return man_holding_phone[0].llm_query("Who is holding the phone?", long_answer=False)

